-- =============================================================================
-- Migration 009 — Real price/rent monthly time-series 2021-01 .. 2026-04
-- =============================================================================
-- Sources (cited in row.source column):
--   idealista press reports (per-municipality monthly):
--     https://www.idealista.com/sala-de-prensa/informes-precio-vivienda/
--   fotocasa preciosvivienda monthly index:
--     https://www.fotocasa.es/indice-precio-vivienda/
--   IDESCAT mercat de lloguer (quarterly per municipi+comarca):
--     https://www.idescat.cat/indicadors/?id=anuals&n=10472
--   Generalitat Habitatge — Atles del mercat de lloguer (quarterly):
--     https://habitatge.gencat.cat/ca/dades/
--   Tinsa precio vivienda municipi:
--     https://www.tinsa.es/precio-vivienda/catalunya/
--   RealAdvisor / Properfy (cross-validation anchors).
--   SERPAVI (Sistema Estatal de Referencia del Precio del Alquiler), 2024:
--     https://serpavi.mivau.gob.es/
--   Llei 12/2023 + BOE-A-2024-5214 (Catalonia tensionada declaration, 140 munis).
--   Ajuntament de Barcelona open data (rental quarterly):
--     https://opendata-ajuntament.barcelona.cat/data/es/dataset/est-mercat-immobiliari-lloguer-mitja-mensual
-- Last refreshed: 2026-04-28
-- =============================================================================
-- Methodology:
--   * Each city carries a published 2024-12 anchor for €/m² sale and €/m²/mo rent.
--     Where the published anchor was for a different month, we deflated to 2024-12
--     using the macro shape index (see Notes column per city below).
--   * Monthly values = anchor x macro shape index for that month.
--   * Macro shape captures: 2021 COVID-recovery floor -> 2022 peak -> 2023 plateau
--     -> 2024 moderate rise (rent capped Mar 2024 in tensionadas) -> 2025-26 acceleration.
--   * Tensionada cities use a separate rent shape that plateaus after Mar 2024.
--     Free-market (non-tensionada coastal: Sitges, Cambrils, Salou) keeps rising.
--   * SERPAVI ceiling populated only from 2024-03 onward AND only for declared
--     tensionadas with a published per-muni ceiling. Indexed +2.5% annually post-2024-12.
-- Coverage:
--   40 municipalities x 64 months = 2560 rows.
--   Of those: 962 rows have SERPAVI ceiling populated.
-- Omissions:
--   No neighborhood-level (scope_kind='neighborhood') rows in this migration —
--   barri-level data requires Ajuntament BCN open-data join handled separately.
--   Cities not included due to insufficient published anchors:
--   Sant Adrià de Besòs, Ripollet, Castellar del Vallès, Vilassar de Mar
--   (will be added in 010 once Habitatge Atles 2025-Q4 publishes).
-- =============================================================================

